import React from 'react';
import s from './Message.module.css';
import { MessageType } from '../HW1';

export type MessagePropsType = {
    message: MessageType;
    currentUserId?: string; // Add the current user ID as a prop
};

const Message = (props: MessagePropsType) => {
    const isOutgoing = props.message.user.name === props.currentUserId; // Compare with current user ID

    return (
        <div
            id={'hw1-message-' + props.message.id}
            className={`${s.message} ${isOutgoing ? s.outgoing : s.incoming}`}>
            <div className={s.imageAndText}>
                <img
                    id={'hw1-avatar-' + props.message.id}
                    src={props.message.user.avatar}
                    alt={props.message.user.name}
                />
                <div className={s.text}>
                    <div id={'hw1-name-' + props.message.id} className={s.name}>
                        <p>{props.message.user.name}</p>
                    </div>
                    <pre id={'hw1-text-' + props.message.id} className={s.messageText}>
                        {props.message.message.text}
                    </pre>
                </div>
            </div>
            <div id={'hw1-time-' + props.message.id} className={s.time}>
                <p>{props.message.message.time}</p>
            </div>
        </div>
    );
};

export default Message;
